import re,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
s=(root/'specification.md').read_text()
def p(en,vi): return {'en':en,'vi':vi}
def quotes(block):
    return re.findall(r'^> (.+)$',block,re.M)
def section(start,end): return s.split(start,1)[1].split(end,1)[0]
lessons=[]
flags=[
 ('karma-and-intention','Karma & Intention','Nhân quả & tác ý','The Moment Before You Reply','Khoảnh khắc trước khi bạn trả lời','9.1 FLAGSHIP A','9.2 FLAGSHIP B','anger','seed'),
 ('impermanence','Impermanence','Vô thường','The Leaf That Would Not Stay','Chiếc lá không thể ở lại','9.2 FLAGSHIP B','9.3 FLAGSHIP C','change','leaf'),
 ('interdependence','Interdependence','Duyên khởi','The Many Lives of a Cup of Tea','Bao nhiêu cuộc đời trong một tách trà','9.3 FLAGSHIP C','9.4 FIVE MORE','relationships','tea')]
questions=[p('What changes when you give yourself three breaths before reacting?','Điều gì có thể thay đổi nếu bạn cho mình ba hơi thở trước khi phản ứng?'),p('What in your life deserves your attention precisely because it will not stay the same?','Điều gì trong đời bạn xứng đáng được trân trọng hơn chính vì nó sẽ không mãi như cũ?'),p('Who or what quietly supports your everyday life?','Ai hay điều gì đang âm thầm nâng đỡ cuộc sống thường ngày của bạn?')]
practices=[p('Before your next difficult reply, notice your body, take three natural breaths, then choose your words.','Trước một lời đáp khó khăn, hãy nhận biết cơ thể, thở tự nhiên ba hơi rồi chọn lời mình muốn nói.'),p('Notice one ordinary detail changing today. You do not need to hold it in place.','Hôm nay, nhận ra một chi tiết bình thường đang đổi thay. Bạn không cần cố giữ nó nguyên vẹn.'),p('With your next cup of tea, remember one person or condition that helped bring it to you.','Khi uống tách trà tiếp theo, nhớ tới một người hay điều kiện đã góp phần đưa nó đến với bạn.')]
expansions=[p('Imagine receiving the same criticism when you are rested, and when you have barely slept. The message is the same; the conditions are different. A pause does not guarantee agreement. It can make room to ask what is true, what needs repairing, and what boundary is necessary.','Thử hình dung bạn nhận cùng một lời phê bình khi đã nghỉ ngơi đủ và khi gần như thức trắng. Tin nhắn giống nhau; điều kiện lại khác. Dừng lại không bảo đảm hai người sẽ đồng ý. Nhưng nó mở ra khoảng trống để hỏi điều gì đúng, điều gì cần sửa và ranh giới nào cần được giữ.'),p('A familiar home may change because someone leaves, a child grows, or a routine ends. We can grieve the old shape of life and still care for the new one. Recognizing change also leaves room to act: protecting a place, asking for help, or making time for someone we love.','Một mái nhà thân quen có thể đổi khác vì ai đó rời đi, một đứa trẻ lớn lên hay nếp sinh hoạt cũ kết thúc. Ta có thể tiếc hình dáng đời sống ngày trước mà vẫn chăm sóc hiện tại. Nhận biết đổi thay cũng dành chỗ cho hành động: gìn giữ một nơi, tìm sự giúp đỡ hoặc dành thời gian cho người mình thương.'),p('If a project goes well, notice the tools, colleagues, time and care that supported it. If it goes badly, look beyond a single person to the conditions that could change. Interdependence does not erase individual responsibility; it gives responsibility a wider and more useful context.','Khi một dự án suôn sẻ, thử nhận ra công cụ, đồng nghiệp, thời gian và sự chăm chút đã nâng đỡ nó. Khi mọi việc không như ý, nhìn xa hơn một cá nhân để tìm điều kiện có thể thay đổi. Duyên khởi không xóa bỏ trách nhiệm mỗi người; nó đặt trách nhiệm vào một bối cảnh rộng và hữu ích hơn.')]
for i,(slug,name,vi,title,tvi,a,b,tag,art) in enumerate(flags):
    q=quotes(section(a,b))
    lessons.append(dict(slug=slug,name=p(name,vi),title=p(title,tvi),intro=p(q[0],q[1]),teaching=[p(q[2],q[3]),expansions[i]],question=questions[i],practice=practices[i],tag=tag,art=art,minutes=4))
more=[
 ('not-self','Not-Self','Vô ngã','A little room to become','Một khoảng trống để đổi thay','Are you the same person you were ten years ago?','Bạn có còn là con người của mười năm trước?',
 'An old photograph catches you by surprise. You remember the person in it, but not all of their wishes feel like yours anymore. The roles, fears and hopes have shifted. Which part did you think had to stay?','Một bức ảnh cũ khiến bạn bất ngờ. Bạn nhớ người trong ảnh, nhưng không phải mong muốn nào của họ cũng còn là của mình. Vai trò, nỗi sợ và hy vọng đã đổi khác. Bạn từng nghĩ phần nào nhất định phải ở lại?',
 'Not-self is not a claim that people are worthless or do not exist. It is an invitation to look carefully at the changing processes we call “me,” rather than gripping a single permanent identity.','Vô ngã không có nghĩa con người vô giá trị hay không hiện hữu. Đó là lời mời quan sát những tiến trình luôn đổi thay mà ta gọi là “tôi”, thay vì bám chặt vào một bản ngã bất biến.',
 'You may have called yourself “the quiet one” for years. In a safer room, with different people, your voice may emerge. A description can help us navigate life, but it does not have to become a prison. We remain accountable for what we do while leaving room to learn.','Bạn có thể đã gọi mình là “người ít nói” suốt nhiều năm. Trong một căn phòng an toàn hơn, giữa những người khác, tiếng nói của bạn có thể xuất hiện. Một mô tả giúp ta hiểu đời sống, nhưng không nhất thiết phải trở thành nhà tù. Ta vẫn chịu trách nhiệm về hành động và dành chỗ để học hỏi.',
 'Write down one old description of yourself that you have outgrown. What could you make room for now?','Viết một mô tả cũ về bản thân mà bạn đã bước qua. Giờ bạn muốn dành chỗ cho điều gì?', 'meaning','self'),
 ('holding-and-letting-go','Holding & Letting Go','Chấp giữ & buông xả','The hand that can open','Bàn tay có thể mở ra','Can you care deeply without holding too tightly?','Ta có thể yêu thương sâu sắc mà không nắm giữ quá chặt không?',
 'You refresh a message, then refresh it again. You cannot make someone reply, but it is hard to stop trying. What would it mean to care for this relationship without controlling every moment of it?','Bạn tải lại tin nhắn, rồi lại tải lại. Bạn không thể khiến ai đó trả lời, nhưng thật khó ngừng cố gắng. Quan tâm tới mối quan hệ này mà không kiểm soát từng khoảnh khắc sẽ như thế nào?',
 'Letting go is not indifference. It may mean loosening the belief that love, success, or safety can be secured by control. Healthy boundaries and caring action still matter.','Buông xả không phải thờ ơ. Đôi khi đó là nới lỏng niềm tin rằng ta có thể giữ mãi tình yêu, thành công hay sự an toàn bằng cách kiểm soát. Ranh giới lành mạnh và hành động có trách nhiệm vẫn rất quan trọng.',
 'A friend cancels a plan. You can honestly name your disappointment and ask for reliability, without deciding what they must feel. Letting go is a practice of choosing where to place your energy. It never requires remaining in a harmful situation.','Một người bạn hủy cuộc hẹn. Bạn có thể nói thật về sự thất vọng và mong muốn được giữ lời, mà không quyết định họ phải cảm thấy gì. Buông xả là thực hành chọn nơi đặt năng lượng. Điều đó không bao giờ yêu cầu bạn ở lại trong hoàn cảnh gây tổn hại.',
 'Name one thing outside your control, and one caring action within it.','Gọi tên một điều ngoài tầm kiểm soát và một hành động quan tâm bạn có thể làm.', 'love','boat'),
 ('mindful-presence','Mindful Presence','Chánh niệm','The moment you almost missed','Khoảnh khắc bạn suýt bỏ quên','When was the last time you truly tasted your tea?','Lần cuối bạn thực sự cảm nhận một ngụm trà là khi nào?',
 'Breakfast disappears while you scroll. You reach the office without remembering the road. Nothing dramatic happened, yet an ordinary piece of your life went by unnoticed. Can you arrive for the next small moment?','Bữa sáng hết lúc nào không hay khi bạn lướt điện thoại. Bạn đến nơi làm việc mà chẳng nhớ con đường. Không có gì lớn lao xảy ra, nhưng một phần đời bình thường đã đi qua mà mình không nhận biết. Bạn có thể có mặt trong khoảnh khắc nhỏ tiếp theo không?',
 'Mindfulness means remembering to notice experience as it happens, with care and without rushing to judge. It does not require being happy all the time.','Chánh niệm là nhớ quay về nhận biết điều đang xảy ra, bằng sự quan tâm và không vội phán xét. Chánh niệm không đòi hỏi ta phải luôn vui vẻ.',
 'At your desk, you might notice the weight of your hands, an ordinary sound, or the fact that you are tired. You do not need to change the feeling into something pleasant. Attention can be gentle and honest at the same time, and you can always stop if an exercise feels uncomfortable.','Ở bàn làm việc, bạn có thể nhận ra trọng lượng bàn tay, một âm thanh bình thường hoặc việc mình đang mệt. Bạn không cần biến cảm giác ấy thành dễ chịu. Sự chú tâm có thể vừa dịu dàng vừa thành thật, và bạn luôn có thể dừng nếu thấy không thoải mái.',
 'Take one ordinary sip or step with deliberate attention.','Uống một ngụm nước hay bước một bước bình thường với sự chú tâm.', 'meaning','breath'),
 ('compassionate-speech','Compassionate Speech','Ái ngữ & từ bi','Truth, spoken gently','Nói thật bằng sự dịu dàng','What could one gentle sentence change?','Một lời dịu dàng có thể thay đổi điều gì?',
 'A friend has cancelled again. You want to say, “You never care about me.” Underneath the accusation is something more vulnerable: you hoped to matter. How can you make that need clear without hiding it in a wound?','Một người bạn lại hủy hẹn. Bạn muốn nói: “Bạn chẳng bao giờ quan tâm tới mình.” Dưới lời trách móc là điều mong manh hơn: bạn hy vọng mình được coi trọng. Làm sao nói rõ nhu cầu ấy mà không giấu nó trong một lời gây đau?',
 'Compassionate speech seeks truth without unnecessary harm. It can be honest, firm, and kind at the same time.','Ái ngữ hướng đến sự chân thật mà không gây thêm tổn thương không cần thiết. Ta có thể vừa thành thật, vừa kiên định, vừa tử tế.',
 'You might say, “I felt disappointed when our plans changed. Can we choose a time you can keep?” The other person may still disagree. A kind sentence is not a method for controlling their response; it is a way of making your own intention more honest and your boundary more understandable.','Bạn có thể nói: “Mình thất vọng khi kế hoạch thay đổi. Mình chọn một giờ bạn có thể giữ được nhé?” Người kia vẫn có thể không đồng ý. Lời tử tế không phải cách kiểm soát phản ứng của họ; đó là cách khiến ý định của bạn thành thật hơn và ranh giới dễ hiểu hơn.',
 'Rewrite one harsh sentence as a clear, respectful request.','Viết lại một câu gay gắt thành lời đề nghị rõ ràng và tôn trọng.', 'relationships','speech'),
 ('rebirth-and-continuity','Rebirth & Continuity','Luân hồi & sự tiếp nối','What the river carries','Điều dòng sông mang theo','What does it mean for something to continue?','Một điều tiếp nối nghĩa là gì?',
 'A phrase your grandmother used appears in your own voice. A kindness offered years ago shapes the way you treat a stranger. Some continuities are familiar; other questions reach beyond what we know. We can explore without pretending certainty.','Một câu bà từng nói xuất hiện trong giọng của bạn. Một sự tử tế từ nhiều năm trước ảnh hưởng tới cách bạn đối xử với người lạ. Có những sự tiếp nối rất thân quen; có những câu hỏi vượt ngoài điều ta biết. Ta có thể tìm hiểu mà không giả vờ chắc chắn.',
 "Buddhist traditions discuss rebirth and continuity in different ways. These are religious and philosophical teachings, not findings proven by this visualization. We can still explore how our actions, care, and influence continue through other people's lives.", 'Các truyền thống Phật giáo bàn về tái sinh và sự tiếp nối theo những cách lý giải khác nhau. Đây là những giáo lý và quan niệm triết học, không phải điều được mô phỏng này chứng minh. Ta vẫn có thể suy ngẫm cách hành động, tình thương và ảnh hưởng của mình tiếp tục hiện diện trong đời người khác.',
 'The river here is an analogy, not a map of an afterlife. Buddhist accounts of rebirth ask philosophical questions about continuity without a permanent self. Interpretations differ across traditions. Separately, we can observe how a person’s care survives in memories, habits and the help we pass on; that observation does not prove religious claims.','Dòng sông ở đây là hình ảnh ví von, không phải bản đồ thế giới sau cái chết. Những lý giải Phật giáo về tái sinh đặt câu hỏi triết học về sự tiếp nối không có bản ngã thường hằng. Các truyền thống có cách hiểu khác nhau. Riêng trong đời sống, ta có thể nhận ra sự quan tâm của một người còn hiện diện trong ký ức, thói quen và giúp đỡ được trao tiếp; điều đó không chứng minh các niềm tin tôn giáo.',
 'Remember a kindness you received. What part of it could you pass on?','Nhớ một sự tử tế bạn đã nhận. Bạn có thể trao tiếp phần nào của điều ấy?', 'meaning','river')]
for slug,en,vi,title,tvi,qe,qv,ie,iv,te,tv,ee,ev,pe,pv,tag,art in more:
    lessons.append(dict(slug=slug,name=p(en,vi),title=p(title,tvi),intro=p(ie,iv),teaching=[p(te,tv),p(ee,ev)],question=p(qe,qv),practice=p(pe,pv),tag=tag,art=art,minutes=3))
for x in lessons:
    x['note']=p('An accessible introduction inspired by Buddhist traditions. Interpretations vary. The scene is a teaching metaphor, not a forecast or scientific demonstration. Further perspectives are collected in the Library.','Bài giới thiệu dễ tiếp cận, lấy cảm hứng từ các truyền thống Phật giáo. Cách lý giải có thể khác nhau. Minh họa là hình ảnh giảng giải, không phải dự đoán hay chứng minh khoa học. Bạn có thể tìm thêm góc nhìn trong Thư viện.')
slugs=['loving-without-owning','why-family-words-hurt','when-effort-is-not-enough','how-much-is-enough','the-other-life-on-your-screen','living-with-absence','forgiveness-and-boundaries','waiting-to-begin-living']
related=['holding-and-letting-go','compassionate-speech','interdependence','holding-and-letting-go','not-self','impermanence','compassionate-speech','mindful-presence']
tags=['love','relationships','change','meaning','meaning','change','relationships','meaning']
prompts=[p('What are you hoping to control because you are afraid of losing it?','Có điều gì bạn đang cố kiểm soát chỉ vì sợ đánh mất?'),p('How could you be honest without making the other person your enemy?','Làm sao nói thật lòng mà không biến người kia thành đối thủ?'),p('Which conditions can you influence—and which can you acknowledge without self-blame?','Bạn có thể tác động đến điều kiện nào, và điều kiện nào cần được chấp nhận mà không tự trách?'),p('What is enough for this chapter of your life?','Ở chặng đường này, thế nào là đủ với bạn?'),p('If you stopped comparing for one afternoon, what might you notice?','Nếu ngừng so sánh trong một buổi chiều, bạn có thể nhận ra điều gì?'),p('Is there one memory you would like to hold with tenderness today?','Hôm nay có ký ức nào bạn muốn nâng niu bằng sự dịu dàng?'),p('What boundary might actually help you remain kind?','Ranh giới nào có thể giúp bạn tiếp tục sống tử tế?'),p('What ordinary moment deserves your full attention today?','Khoảnh khắc bình thường nào hôm nay xứng đáng được bạn chú tâm trọn vẹn?')]
invitations=[p('Today, replace one attempt to monitor with one honest conversation. Name a need rather than testing whether someone can guess it. Care can be close without becoming possession.','Hôm nay, thử thay một lần kiểm soát bằng một cuộc trò chuyện thành thật. Nói rõ nhu cầu thay vì thử xem người kia có đoán được không. Sự quan tâm có thể gần gũi mà không thành sở hữu.'),p('Before the next conversation, write the one thing you wish the other person understood. You can choose a quieter time, ask to be heard, or end the conversation if it becomes harmful.','Trước cuộc trò chuyện tiếp theo, viết một điều bạn mong người kia hiểu. Bạn có thể chọn lúc yên hơn, đề nghị được lắng nghe hoặc kết thúc nếu cuộc nói chuyện gây tổn hại.'),p('Make two small lists: what you could influence, and what you could not. Choose one condition to improve. The outcome of one project is not the whole story of your worth.','Lập hai danh sách nhỏ: điều bạn có thể tác động và điều bạn không thể. Chọn một điều kiện để cải thiện. Kết quả của một dự án không phải toàn bộ giá trị của bạn.'),p('Define enough in concrete terms for this season: a safe home, an emergency reserve, a meal shared without hurry. A useful financial plan can include both needs and time to live.','Ở giai đoạn này, thử định nghĩa sự đủ bằng điều cụ thể: mái nhà an toàn, khoản dự phòng, bữa cơm không vội. Một kế hoạch tài chính hữu ích có thể dành chỗ cho cả nhu cầu và thời gian sống.'),p('Put the screen aside for a few minutes. Notice one thing in your actual room. You may choose to follow fewer accounts or to take a break; attention is something you can care for.','Đặt màn hình sang bên vài phút. Nhận ra một điều trong căn phòng thật của mình. Bạn có thể bớt theo dõi vài tài khoản hoặc nghỉ một lúc; sự chú tâm cũng cần được chăm sóc.'),p('There is no required lesson to extract from loss. If you want, write one memory or ask someone to sit with you. Support from trusted people and appropriate care can matter more than finding the right words.','Không có bài học bắt buộc nào phải rút ra từ mất mát. Nếu muốn, viết một ký ức hoặc nhờ ai đó ngồi bên. Sự nâng đỡ từ người tin cậy và chăm sóc phù hợp có thể quan trọng hơn tìm đúng lời.'),p('Try one clear sentence: “I care, and I cannot agree to this.” You do not have to offer endless explanations. A boundary may protect your ability to care, and it can be revised as circumstances change.','Thử một câu rõ ràng: “Mình quan tâm, nhưng không thể đồng ý chuyện này.” Bạn không cần giải thích mãi. Ranh giới có thể bảo vệ khả năng quan tâm của bạn và được điều chỉnh khi hoàn cảnh đổi khác.'),p('Let one small part of today be more than a task to finish. Taste your food, notice the light, or listen without planning your reply. The life you are building is already happening.','Để một phần nhỏ hôm nay không chỉ là công việc cần hoàn thành. Cảm nhận món ăn, nhìn ánh sáng hoặc lắng nghe mà không soạn sẵn câu trả lời. Cuộc đời bạn đang xây dựng đã bắt đầu rồi.')]
stories=[]
for i in range(8):
    block=section('## Story '+str(i+1)+' —','## Story '+str(i+2)+' —' if i<7 else '**For all story details:**')
    titles=re.findall(r'- Title (?:EN|VI): \*\*(.*?)\*\*',block)
    q=quotes(block)
    stories.append(dict(slug=slugs[i],title=p(*titles),body=p(q[0],q[1]),question=prompts[i],practice=invitations[i],related=related[i],tag=tags[i],minutes=2))
sessions=[]
for i,key in enumerate(['A','B','C','D']):
    block=section('### Session '+key+' —','### Session '+chr(ord(key)+1)+' —' if key!='D' else '## 11.5')
    title=re.search(r'^(.*?) / (.*?) \(',block.strip()).groups()
    en=re.findall(r'\*\*\d+% EN:\*\* `([^`]+)`',block)
    vi=re.findall(r'\*\*\d+% VI:\*\* `([^`]+)`',block)
    sessions.append(dict(id=['returning','emotions','rest','gratitude'][i],title=p(*title),duration=600 if i==2 else 300,mode='guided',cues=[p(a,b) for a,b in zip(en,vi)]))
manifest=quotes(section('## 2.3 Brand manifesto','## 2.4'))
about=quotes(section('Suggested founder-neutral copy','# 15.'))
data=dict(lessons=lessons,stories=stories,sessions=sessions,manifest=p(*manifest),about=p(*about))
(root/'src/content.js').write_text('export const content = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n')
print(json.dumps({k:len(data[k]) for k in ['lessons','stories','sessions']}))
